// Fixed slow recovery from an ALL-valid-observation periodic regression.
#include "phase_motion.hpp"
#include "full_mode.hpp"
using namespace phasejoint;
// Fixed-slow forward-model projection. No free slow state or sensor nuisance.
int main(int argc,char**argv){try{
 if(argc!=8 || std::string(argv[7])!="full_observation"){std::cerr<<"slow_run raw_input decomposition_dir output initScale coefficientPriorScale full_observation\n";return 2;}
 std::string sr=argv[1],input=argv[2],dec=argv[3],out=argv[4];double init=std::stod(argv[5]),prior=std::stod(argv[6]);if(std::filesystem::exists(out))throw std::runtime_error("Refuse existing recovery output");std::filesystem::create_directories(out);
 auto settings=read(sr+"/query_settings.csv")[0],status=read(sr+"/solver.csv")[0];double start=settings[1],end=settings[2],qt=settings[3],qr=settings[4],delay=settings[5];Vec3 lever=vec(settings,6),ba=vec(status,11),bg=vec(status,14);
 std::vector<State>knots;for(auto r:read(sr+"/knots.csv"))knots.emplace_back(r[0],SO3d(Eigen::Quaterniond(r[13],r[10],r[11],r[12])),vec(r,14),vec(r,17),vec(r,1),vec(r,4),vec(r,7));
 double t0=knots.front().t,finish=knots.back().t,dt=(finish-t0)/(knots.size()-1);auto mixer=std::make_shared<GPMixer>(dt,qr*Mat3::Identity(),qt*Mat3::Identity());GaussianProcess gp(mixer);gp.setStartTime(t0);gp.extendKnotsTo(finish,State(),false);for(size_t i=0;i<knots.size();++i)gp.setKnot(i,knots[i]);auto slow=[&](double t){return auditedQuery(gp,t);};
 PhaseCurve phase(sr+"/phase_pieces.csv");const int H=3;std::vector<double>coeff(36,0);for(int i=0;i<36;++i){int h=(i%18)/6+1;coeff[i]=init*(i<18?.05/(h*h):.05/h)*std::sin(i+1.);}
 auto acc=read(input+"/accel.csv"),gyro=read(input+"/gyro.csv"),gps=read(input+"/gnss.csv");verifyFull(acc,gyro,gps);auto aper=read(dec+"/accel_decomposition.csv"),gper=read(dec+"/gyro_decomposition.csv");ceres::Problem problem;std::vector<ceres::ResidualBlockId>dataIds;int na=0,ng=0,nn=0;
 for(int kind=0;kind<2;++kind){const auto&rows=kind==0?acc:gyro;const auto&per=kind==0?aper:gper;if(rows.size()!=per.size())throw std::runtime_error("Decomposition row count");
  for(size_t k=0;k<rows.size();++k){const auto&r=rows[k];double t=r[0];if(std::abs(t-per[k][0])>1e-9)throw std::runtime_error("Native timestamp mismatch");if(r[4]!=0||r[5]==0||t<t0||t>=finish||!phase.valid(t))continue;int j=std::floor((t-t0)/dt);auto p=params(knots[j],knots[j+1]);p.insert(p.end(),{coeff.data(),bg.data(),ba.data()});Vec3 target=predicted(slow(t),kind,lever)+vec(per[k],1)+(kind==0?ba:bg);
   auto*f=new PhaseFactor(mixer,(t-knots[j].t)/dt,phase.query(t),3,kind,target,Mat3::Identity()/(kind==0?1.5:.05),lever);dataIds.push_back(problem.AddResidualBlock(f,new ceres::HuberLoss(3),p));if(kind==0)++na;else ++ng;}}
 for(auto r:gps){double t=r[0]-delay;if(r[43]!=0||r[44]==0||t<t0||t>=finish||!phase.valid(t))continue;int j=std::floor((t-t0)/dt);auto p=params(knots[j],knots[j+1]);p.insert(p.end(),{coeff.data(),bg.data(),ba.data()});Mat6 cov;for(int a=0;a<6;++a)for(int b=0;b<6;++b)cov(a,b)=r[7+6*a+b];Vec6 obs;obs<<vec(r,1),vec(r,4);Mat6 W=cov.llt().matrixL().solve(Mat6::Identity());dataIds.push_back(problem.AddResidualBlock(new PhaseFactor(mixer,(t-knots[j].t)/dt,phase.query(t),3,2,obs,W,lever),new ceres::HuberLoss(3),p));++nn;}
 for(auto&k:knots)for(auto p:{k.R.data(),k.O.data(),k.S.data(),k.P.data(),k.V.data(),k.A.data()})if(problem.HasParameterBlock(p))problem.SetParameterBlockConstant(p);
 problem.SetParameterBlockConstant(ba.data());problem.SetParameterBlockConstant(bg.data());if(prior>0)problem.AddResidualBlock(new CoefficientPrior(3,.05*prior,.05*prior),nullptr,coeff.data());
 ceres::Solver::Options opts;opts.linear_solver_type=ceres::DENSE_QR;opts.max_num_iterations=100;opts.num_threads=2;opts.function_tolerance=1e-10;opts.gradient_tolerance=1e-10;opts.parameter_tolerance=1e-10;ceres::Solver::Summary summary;ceres::Solve(opts,&problem,&summary);
 std::ofstream log(out+"/solver.txt");log<<summary.FullReport();std::ofstream result(out+"/solver.csv");result<<"usable,termination,initial_cost,final_cost,iterations,time_s,local_parameters,accel_factors,gyro_factors,gnss_factors,phase_boundary_excluded,ba_x,ba_y,ba_z,bg_x,bg_y,bg_z\n"<<std::setprecision(17)<<summary.IsSolutionUsable()<<','<<summary.termination_type<<','<<summary.initial_cost<<','<<summary.final_cost<<','<<summary.iterations.size()<<','<<summary.total_time_in_seconds<<",36,"<<na<<','<<ng<<','<<nn<<",0";for(auto v:{ba,bg})for(int j=0;j<3;++j)result<<','<<v[j];result<<'\n';
 std::ofstream cp(out+"/coefficients.csv");cp<<"index,value,prior_sigma\n"<<std::setprecision(17);for(int i=0;i<36;++i){int h=(i%18)/6+1;cp<<i<<','<<coeff[i]<<','<<(i<18?.05/(h*h):.05/h)*prior<<'\n';}
 std::filesystem::copy_file(sr+"/knots.csv",out+"/knots.csv");std::filesystem::copy_file(sr+"/phase_pieces.csv",out+"/phase_pieces.csv");std::ofstream ss(out+"/query_settings.csv");ss<<"H,start,end,qt,qr,delay,lx,ly,lz\n3"<<std::setprecision(17);for(int i=1;i<9;++i)ss<<','<<settings[i];ss<<'\n';
 auto query=[&](double t){return compose(slow(t),phase.query(t),coeff.data(),3);};std::ofstream dense(out+"/trajectory.csv"),sd(out+"/slow_trajectory.csv");dense<<stateHeader;sd<<stateHeader;for(double t=start;t<=end+1e-8;t+=.005){writeState(dense,query(std::min(t,end)));writeState(sd,slow(std::min(t,end)));}
 for(int kind=0;kind<3;++kind){const auto&rows=kind==0?acc:kind==1?gyro:gps;int dim=kind==2?6:3;std::ofstream f(out+(kind==0?"/accel_predictions.csv":kind==1?"/gyro_predictions.csv":"/gnss_predictions.csv"));f<<"t,holdout,valid,fix";for(std::string label:{"obs","pred","white","slowpred","addback"})for(int j=0;j<dim;++j)f<<','<<label<<j;f<<'\n';
  for(size_t k=0;k<rows.size();++k){auto r=rows[k];double t=r[0]-(kind==2?delay:0);if(t<start||t>end)continue;auto pred=predicted(query(t),kind,lever),spred=predicted(slow(t),kind,lever);Eigen::VectorXd obs(dim),white(dim),add(dim);int hi=kind==2?43:4,vi=kind==2?44:5;
   if(kind<2){pred+=kind==0?ba:bg;spred+=kind==0?ba:bg;obs=vec(r,1);white=(pred-obs)/(kind==0?1.5:.05);add=spred+vec((kind==0?aper:gper)[k],1);}else{obs<<vec(r,1),vec(r,4);Mat6 cov;for(int a=0;a<6;++a)for(int b=0;b<6;++b)cov(a,b)=r[7+6*a+b];white=cov.llt().matrixL().solve(pred-obs);add=spred;}
   f<<std::setprecision(17)<<t<<','<<r[hi]<<','<<r[vi]<<','<<(kind==2?r[45]:0);for(auto v:{obs,pred,white,spred,add})for(int j=0;j<dim;++j)f<<','<<v[j];f<<'\n';}}
 std::ofstream kin(out+"/kinematics.csv");kin<<"test,h,p,v,R,omega,a,alpha\n";
 for(double h:{1e-4,1e-5,1e-6}){Eigen::Vector4d worst=Eigen::Vector4d::Zero();for(double t=start+.003173;t<end-.003;t+=.01373){auto x=query(t),l=query(t-h),r=query(t+h);Eigen::Vector4d e;e<<((r.P-l.P)/(2*h)-x.V).norm(),((r.V-l.V)/(2*h)-x.A).norm(),((l.R.inverse()*r.R).log()/(2*h)-x.O).norm(),((r.O-l.O)/(2*h)-x.S).norm();worst=worst.cwiseMax(e);}kin<<"derivative,"<<h;for(double v:worst)kin<<','<<v;kin<<",0,0\n";}
 for(double h:{1e-7,1e-9,1e-11}){Eigen::Matrix<double,6,1>worst=Eigen::Matrix<double,6,1>::Zero();for(int i=1;i<int(knots.size())-1;++i){double t=knots[i].t;if(t<start||t>end)continue;auto l=query(t-h),r=query(t+h);Eigen::Matrix<double,6,1>e;e<<(r.P-l.P).norm(),(r.V-l.V).norm(),(l.R.inverse()*r.R).log().norm(),(r.O-l.O).norm(),(r.A-l.A).norm(),(r.S-l.S).norm();worst=worst.cwiseMax(e);}kin<<"boundary,"<<h;for(double v:worst)kin<<','<<v;kin<<'\n';}
 std::ofstream integ(out+"/integration.csv");integ<<"duration,step,p,v,R,omega,left_endpoint_v,left_endpoint_omega\n";
 for(double duration:{.02,.2,.5})for(double step:{.005,.00125,.0003125}){Eigen::Matrix<double,6,1>worst=Eigen::Matrix<double,6,1>::Zero();for(double t=start+.10317;t+duration<end-.1;t+=.3713){auto a=query(t),b=query(t+duration);Vec3 dp=Vec3::Zero(),dv=dp,dw=dp;SO3d R=a.R;int count=std::ceil(duration/step);double h=duration/count;for(int j=0;j<count;++j){auto x=query(t+(j+.5)*h);dp+=x.V*h;dv+=x.A*h;dw+=x.S*h;R=R*SO3d::exp(x.O*h);}Eigen::Matrix<double,6,1>e;e<<(a.P+dp-b.P).norm(),(a.V+dv-b.V).norm(),(R.inverse()*b.R).log().norm(),(a.O+dw-b.O).norm(),(a.V+a.A*duration-b.V).norm(),(a.O+a.S*duration-b.O).norm();worst=worst.cwiseMax(e);}integ<<duration<<','<<step;for(double v:worst)integ<<','<<v;integ<<'\n';}

 // Conditional information only: excludes coefficient prior, does not include
 // uncertainty of learned template, slow curve, timings, or correlated samples.
 ceres::Problem::EvaluateOptions eo;eo.parameter_blocks={coeff.data()};eo.residual_blocks=dataIds;eo.apply_loss_function=false;ceres::CRSMatrix J;problem.Evaluate(eo,nullptr,nullptr,nullptr,&J);Eigen::MatrixXd jac=Eigen::MatrixXd::Zero(J.num_rows,36);for(int r=0;r<J.num_rows;++r)for(int k=J.rows[r];k<J.rows[r+1];++k)jac(r,J.cols[k])=J.values[k];Eigen::MatrixXd info=jac.transpose()*jac;
 std::ofstream inf(out+"/coefficient_information.csv");inf<<"row";for(int j=0;j<36;++j)inf<<",c"<<j;inf<<'\n';for(int i=0;i<36;++i){inf<<i;for(int j=0;j<36;++j)inf<<','<<std::setprecision(17)<<info(i,j);inf<<'\n';}
 std::ofstream jm(out+"/jacobian_monitor.csv");jm<<"t,kind,coefficient_error\n";for(double t=start+.01317;t<end;t+=1.73){int j=std::floor((t-t0)/dt);auto p=params(knots[j],knots[j+1]);p.insert(p.end(),{coeff.data(),bg.data(),ba.data()});for(int kind:{0,1,2}){int dim=kind==2?6:3;PhaseFactor f(mixer,(t-knots[j].t)/dt,phase.query(t),3,kind,Eigen::VectorXd::Zero(dim),Eigen::MatrixXd::Identity(dim,dim),lever);jm<<t<<','<<kind<<','<<jacobianError(f,p,1e-6,12,13)<<'\n';}}
 std::cout<<summary.BriefReport()<<'\n';return summary.IsSolutionUsable()?0:3;
 }catch(const std::exception&e){std::cerr<<e.what()<<'\n';return 2;}}
